const state = {
  query: "",
  category: "all",
  type: "all",
  favoritesOnly: false,
  favorites: new Set(JSON.parse(localStorage.getItem("myprompt-favorites") || "[]")),
  activePrompt: null
};

const $ = s => document.querySelector(s);
const rows = $("#rows");
const chips = $("#categoryChips");
const searchInput = $("#searchInput");
const searchResults = $("#searchResults");
const searchGrid = $("#searchGrid");
const modalBackdrop = $("#modalBackdrop");
const resultCount = $("#resultCount");

function saveFavs() {
  localStorage.setItem("myprompt-favorites", JSON.stringify([...state.favorites]));
}

function isFav(id) { return state.favorites.has(id); }

function toggleFav(id) {
  if (isFav(id)) state.favorites.delete(id); else state.favorites.add(id);
  saveFavs(); render();
  if (state.activePrompt?.id === id) updateModalFav();
}

function card(p) {
  const el = document.createElement("article");
  el.className = "card";
  el.innerHTML = `
    <button class="fav-btn ${isFav(p.id) ? "active" : ""}" title="บันทึกรายการโปรด">${isFav(p.id) ? "♥" : "♡"}</button>
    <div class="card-cover ${p.type === "วิดีโอ" ? "video" : ""}">
      <span class="card-num">#${String(p.id).padStart(3,"0")}</span>
      <span class="big-icon">${p.type === "วิดีโอ" ? "▶" : "✦"}</span>
    </div>
    <div class="card-body">
      <h4>${escapeHtml(p.title)}</h4>
      <div class="card-meta"><span>${escapeHtml(p.categoryName)}</span><span>${p.type}</span></div>
    </div>`;
  el.addEventListener("click", e => {
    if (e.target.closest(".fav-btn")) return;
    openModal(p);
  });
  el.querySelector(".fav-btn").addEventListener("click", e => {
    e.stopPropagation(); toggleFav(p.id);
  });
  return el;
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
}

function filtered() {
  let data = PROMPTS;
  if (state.category !== "all") data = data.filter(p => p.category === state.category);
  if (state.type !== "all") data = data.filter(p => p.type === state.type);
  if (state.favoritesOnly) data = data.filter(p => isFav(p.id));
  if (state.query.trim()) {
    const q = state.query.trim().toLowerCase();
    data = data.filter(p => [p.title,p.categoryName,p.type,p.prompt,...p.tags].join(" ").toLowerCase().includes(q));
  }
  return data;
}

function renderChips() {
  chips.innerHTML = "";
  const all = document.createElement("button");
  all.className = "chip " + (state.category === "all" ? "active" : "");
  all.textContent = "ทั้งหมด";
  all.onclick = () => {state.category="all"; state.favoritesOnly=false; render();};
  chips.appendChild(all);
  CATEGORIES.forEach(c => {
    const b = document.createElement("button");
    b.className = "chip " + (state.category === c.id ? "active" : "");
    b.textContent = c.name;
    b.onclick = () => {state.category=c.id; state.favoritesOnly=false; render();};
    chips.appendChild(b);
  });
}

function renderRows() {
  rows.innerHTML = "";
  const data = filtered();
  resultCount.textContent = `พบ ${data.length} จาก ${PROMPTS.length} Prompt`;

  if (state.query.trim()) {
    searchResults.classList.remove("hidden");
    searchGrid.innerHTML = "";
    data.forEach(p => searchGrid.appendChild(card(p)));
    rows.classList.add("hidden");
    return;
  }
  searchResults.classList.add("hidden");
  rows.classList.remove("hidden");

  if (state.favoritesOnly) {
    const wrap = document.createElement("section");
    wrap.className = "search-results";
    wrap.innerHTML = `<div class="section-head"><h2>รายการโปรด</h2><span style="color:#74849b;font-size:12px">${data.length} รายการ</span></div>`;
    const grid = document.createElement("div"); grid.className="grid";
    data.forEach(p => grid.appendChild(card(p)));
    if (!data.length) grid.innerHTML = `<p style="color:#8090a6">ยังไม่มีรายการโปรด กด ♡ บน Prompt ที่ต้องการเก็บไว้ได้เลย</p>`;
    wrap.appendChild(grid); rows.appendChild(wrap); return;
  }

  const groups = state.category === "all" ? CATEGORIES : CATEGORIES.filter(c => c.id === state.category);
  groups.forEach(c => {
    let items = data.filter(p => p.category === c.id);
    if (!items.length) return;
    const section = document.createElement("section");
    section.className = "prompt-row";
    section.innerHTML = `<div class="row-title"><h3>${c.name}</h3><span>${items.length} Prompt</span></div>`;
    const scroller = document.createElement("div"); scroller.className = "row-scroll";
    items.forEach(p => scroller.appendChild(card(p)));
    section.appendChild(scroller); rows.appendChild(section);
  });
}

function render() { renderChips(); renderRows(); syncNav(); }

function syncNav() {
  document.querySelectorAll(".nav-link").forEach(x => x.classList.remove("active"));
  if (state.favoritesOnly) $("#favoriteNav").classList.add("active");
  else if (state.type === "all") document.querySelector('[data-filter="all"]').classList.add("active");
  else {
    const node = document.querySelector(`[data-type-filter="${state.type}"]`);
    if (node) node.classList.add("active");
  }
}

function openModal(p) {
  state.activePrompt = p;
  $("#modalType").textContent = p.type;
  $("#modalTitle").textContent = p.title;
  $("#modalMeta").textContent = `#${String(p.id).padStart(3,"0")} • ${p.categoryName} • ${p.tags.join(" • ")}`;
  $("#modalPrompt").textContent = p.prompt;
  updateModalFav();
  modalBackdrop.classList.remove("hidden");
  document.body.style.overflow = "hidden";
}

function closeModal() {
  modalBackdrop.classList.add("hidden");
  document.body.style.overflow = "";
}

function updateModalFav() {
  if (!state.activePrompt) return;
  const b = $("#favModalBtn");
  b.textContent = isFav(state.activePrompt.id) ? "♥ บันทึกแล้ว" : "♡ บันทึก";
}

async function copyPrompt(p) {
  try {
    await navigator.clipboard.writeText(p.prompt);
  } catch(e) {
    const ta=document.createElement("textarea"); ta.value=p.prompt; document.body.appendChild(ta); ta.select(); document.execCommand("copy"); ta.remove();
  }
  showToast("คัดลอก Prompt แล้ว ✨");
}

function showToast(msg) {
  const t=$("#toast"); t.textContent=msg; t.classList.add("show");
  clearTimeout(window.__toast); window.__toast=setTimeout(()=>t.classList.remove("show"),1800);
}

function randomPrompt() {
  const pool = filtered().length ? filtered() : PROMPTS;
  const p = pool[Math.floor(Math.random()*pool.length)];
  openModal(p);
}

searchInput.addEventListener("input", e => {state.query=e.target.value; render();});
$("#clearSearch").onclick = () => {searchInput.value=""; state.query=""; render(); searchInput.focus();};
$("#copyModalBtn").onclick = () => state.activePrompt && copyPrompt(state.activePrompt);
$("#favModalBtn").onclick = () => state.activePrompt && toggleFav(state.activePrompt.id);
$("#closeModal").onclick = closeModal;
modalBackdrop.addEventListener("click", e => {if(e.target===modalBackdrop)closeModal();});
document.addEventListener("keydown", e => {
  if ((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==="k") {e.preventDefault(); searchInput.focus();}
  if(e.key==="Escape") closeModal();
});
$("#randomBtn").onclick=randomPrompt; $("#heroRandomBtn").onclick=randomPrompt;
$("#exploreBtn").onclick=()=>$("#library").scrollIntoView({behavior:"smooth"});
document.querySelector('[data-filter="all"]').onclick=()=>{state.type="all";state.category="all";state.favoritesOnly=false;render();};
document.querySelectorAll("[data-type-filter]").forEach(b=>b.onclick=()=>{state.type=b.dataset.typeFilter;state.category="all";state.favoritesOnly=false;render();});
$("#favoriteNav").onclick=()=>{state.favoritesOnly=true;state.type="all";state.category="all";render();};

render();
